import base64, re, sys, binascii
text = open('/challenge/attachment/maze.pt','rb').read().decode(errors='ignore')
# find base64-like substrings (letters digits + /, =)
bs = re.findall(r'[A-Za-z0-9_/+=]{20,}', text)
for b in bs:
    try:
        decoded = base64.b64decode(b).decode('utf-8')
        print('found:', b[:30], '->', decoded)
    except Exception as e:
        pass

