    data = pickle.load(f)
print(type(data))
if isinstance(data, dict):
    print('keys:', data.keys())
    # maybe contains maze as a tensor converted to list
    for k,v in data.items():
        print('---', k, type(v))
        if hasattr(v, 'shape'):
            print('shape', v.shape)
        if isinstance(v, list):
            print('list length', len(v))
        if isinstance(v, (bytes, bytearray)):
            print('bytes len', len(v))
        # attempt to see if contains numbers
    # try to see 'maze' key
    if 'maze' in data:
        print('maze entry', data['maze'])
else:
    print('repr', repr(data)[:500])

